#
# t_pseudo.jl
#
# To compare the pseudo-particle Green's functions with NESSi, point by
# point: the storage convention, pseudo_convolution (with the density
# matrix), pseudo_dyson (matrix, function, and scalar Hamiltonians), and
# pseudo_vie2, including the lesser start-up source blocks j > n. The data
# are generated by .nessi/kbref/pseudo_reference.cpp, whose closed-form
# inputs are rebuilt here with exactly the same formulas (nothing is read
# back from the output, except the storage file which is the input itself).
#
# NESSi reference: libcntr/cntr/cntr_herm_pseudo_impl.hpp,
# cntr_pseudo_convolution_impl.hpp, cntr_pseudodyson_impl.hpp, and
# cntr_pseudo_vie2_impl.hpp. There is no pseudo-particle Catch test.
#
# Primary gate: every entry with atol = rtol = 1e-10.
#

isdefined(Main, :kb_test_profile) ||
    include(joinpath(@__DIR__, "..", "common", "profile.jl"))

using LinearAlgebra

const P6_DATA = joinpath(@__DIR__, "data", "phase6")
const P6_NT = 10
const P6_NTAU = 30
const P6_BETA = 2.0
const P6_H = 0.02
const P6_LAM0 = 0.5

# See pseudo_reference.cpp, val() and build()
function p6_val(w, c, x, y, a, b)
    amp = 0.3 + 0.1w + 0.05c + 0.1a - 0.07b
    env = exp(-0.2x - 0.15y)
    return amp * env * complex(cos(0.7x + 0.3y + 0.2(a + b) + w),
                               sin(0.5x - 0.4y + 0.1a * b + c))
end
p6_blk(w, c, x, y, d, s) = C64[s * p6_val(w, c, x, y, a, b) for a = 0:d-1, b = 0:d-1]

p6_cn(d) = Cn(P6_NT + 1, P6_NTAU + 1, d, d, P6_NT * P6_H, P6_BETA)

function p6_build!(G::PseudoGF, w, s)
    d = getdims(G)[1]
    δτ = P6_BETA / P6_NTAU
    for q = 0:P6_NTAU
        G.mat[q+1] = p6_blk(w, 0, q * δτ, 0.0, d, s)
    end
    for i = 0:P6_NT
        for j = 0:i
            G.gtr[i+1,j+1] = p6_blk(w, 1, i * P6_H, j * P6_H, d, s)
        end
        for q = 0:P6_NTAU
            G.lmix[i+1,q+1] = p6_blk(w, 2, i * P6_H, q * δτ, d, s)
        end
        for j = i:P6_NT
            G.less[i+1,j+1] = p6_blk(w, 3, i * P6_H, j * P6_H, d, s)
        end
    end
    return G
end

function p6_ham(d, t)
    M = C64[0.3 0.2-0.1im; 0.2+0.1im -0.4] + 0.3 * sin(2t) * I
    return M[1:d, 1:d]
end
p6_middle(d, t) = C64[1+0.2t 0.1+0.3im*t; -0.2+0.05im 0.8][1:d, 1:d]

# H[0] = H(0) (Matsubara axis), H[n] = H((n - 1) h)
function p6_hcf(d)
    H = Cf(P6_NT + 1, d, d)
    H[0] = p6_ham(d, 0.0)
    for n = 1:P6_NT+1
        H[n] = p6_ham(d, (n - 1) * P6_H)
    end
    return H
end

function p6_fcf(d)
    f = Cf(P6_NT + 1, d, d)
    f[0] = p6_middle(d, -0.5)
    for n = 1:P6_NT+1
        f[n] = p6_middle(d, (n - 1) * P6_H)
    end
    return f
end

#
# Compare all the storage rows (mat, gtr, tv, les) with G. Returns the
# maximal absolute error.
#
function p6_storage(G::PseudoGF, ref::KbrefData)
    err = 0.0
    nfail = 0
    for r in ref.rows
        r.component in ("mat", "gtr", "tv", "les") || continue
        v = kb_value(G, r)
        err = max(err, abs(v - r.value))
        if !isapprox(v, r.value; atol = 1e-10, rtol = 1e-10)
            nfail += 1
            nfail ≤ 5 && @error "pseudo mismatch" case = ref.metadata["case"] row = r kb = v
        end
    end
    @test nfail == 0
    return err
end

#
# Compare the lesser start-up source blocks les_start_source(j,n), j > n,
# with the KB private scratch-target convolutions. A, Acc are Σ (Dyson,
# alpha = 1) or F, Fcc (VIE2, alpha = -1).
#
function p6_start_source(G, A, Acc, I, α, ref::KbrefData; nonzero = true)
    k = I.k
    d = getdims(G)[1]
    rows = filter(r -> r.component == "les_start_source", ref.rows)
    @test length(rows) == d * d * k * (k + 1) ÷ 2
    cws = KadanoffBaym._ConvWorkspace(A, G)
    err = 0.0
    nfail = 0
    for n = 0:k-1
        tstp = n + 1
        buf = [zeros(C64, d, d) for _ = 0:k]
        KadanoffBaym._incr_convolution_lmix_rmix!(buf, tstp, A, Acc, nothing, G, G,
                                                  I, P6_BETA, P6_H, α, cws)
        KadanoffBaym._incr_convolution_less_adv!(buf, tstp, A, Acc, nothing, G, G,
                                                 I, P6_BETA, P6_H, α, cws)
        for r in rows
            r.j == n || continue
            v = buf[r.i+1][r.a+1, r.b+1]
            err = max(err, abs(v - r.value))
            isapprox(v, r.value; atol = 1e-10, rtol = 1e-10) || (nfail += 1)
        end
        # The public slice-target API gives the blocks j ≤ n only, and they
        # agree with the scratch buffer
        W = PseudoGF(p6_cn(d), getsign(G))
        incr_convolution_lmix_rmix!(tstp, W, A, Acc, nothing, G, G, I, P6_BETA, P6_H, α)
        incr_convolution_less_adv!(tstp, W, A, Acc, nothing, G, G, I, P6_BETA, P6_H, α)
        @test all(j -> W.less[j,tstp] ≈ buf[j], 1:tstp)
    end
    # The blocks j > n are nonzero, i.e., they matter in the start-up
    # (they vanish identically for Σ = 0)
    nonzero && @test maximum(r -> abs(r.value), rows) > 1e-6
    @test nfail == 0
    return err
end

p6_read(name) = read_kbref(joinpath(P6_DATA, name * ".dat"))
p6_meta(ref) = (d = parse(Int, ref.metadata["size1"]), k = parse(Int, ref.metadata["k"]),
                sig = parse(Int, ref.metadata["sig"]))

@testset verbose = true "NESSi: pseudo-particle Green's functions" begin
    files = filter(f -> endswith(f, ".dat"), readdir(P6_DATA))
    @test length(files) == 18
    consumed = Set{String}()

    @testset "storage convention" begin
        ref = p6_read("pseudo_storage")
        push!(consumed, "pseudo_storage.dat")
        G = p6_build!(PseudoGF(p6_cn(2), FERMI), 0, 1.0)
        err = p6_storage(G, ref)
        # Derived accessors from the independent storage rows
        tv = Dict((r.i, r.j) => r for r in ref.rows if r.component == "tv")
        mat = Dict((r.i, r.a, r.b) => r.value for r in ref.rows if r.component == "mat")
        gtr = Dict((r.i, r.j, r.a, r.b) => r.value for r in ref.rows if r.component == "gtr")
        ξ = getsign(G)
        for q = 0:P6_NTAU, a = 0:1, b = 0:1
            # Gᴹ(-τ) = ξ Gᴹ(β - τ)
            @test G.matm[q+1][a+1,b+1] ≈ ξ * mat[(P6_NTAU - q, a, b)] atol = 1e-12
        end
        for q = 0:P6_NTAU, i = 0:P6_NT
            # G^⌈(τ,t) = -ξ G^⌉(t,β-τ)†
            X = G.rmix[q+1,i+1]
            Y = -ξ * adjoint(G.lmix[i+1,P6_NTAU-q+1])
            @test X ≈ Y atol = 1e-12
        end
        for i = 0:P6_NT, j = i+1:P6_NT, a = 0:1, b = 0:1
            # G^{>}(i,j) = -G^{>}(j,i)†, j > i
            @test G.gtr[i+1,j+1][a+1,b+1] ≈ -conj(gtr[(j, i, b, a)]) atol = 1e-12
        end
        @test err < 1e-12
        @info "pseudo storage: max error $err"
    end

    @testset "pseudo_convolution: $name" for name in filter(f -> startswith(f, "pseudo_convolution"), files)
        ref = read_kbref(joinpath(P6_DATA, name))
        push!(consumed, name)
        (; d, k, sig) = p6_meta(ref)
        C = p6_cn(d)
        A, Acc, B, Bcc = (p6_build!(PseudoGF(C, sig), w, 1.0) for w = 1:4)
        f = ref.metadata["f"] == "yes" ? p6_fcf(d) : nothing
        I = Integrator(k)
        X = PseudoGF(C, sig)
        pseudo_convolution!(X, A, Acc, f, B, Bcc, I, P6_BETA, P6_H)
        err = p6_storage(X, ref)
        nfail = 0
        for r in ref.rows
            r.component == "density" || continue
            ρ = convolution_density_matrix(r.i + 1, A, Acc, f, B, Bcc, I, P6_BETA, P6_H)
            v = ρ[r.a+1, r.b+1]
            err = max(err, abs(v - r.value))
            isapprox(v, r.value; atol = 1e-10, rtol = 1e-10) || (nfail += 1)
        end
        @test count(r -> r.component == "density", ref.rows) == d * d * (P6_NT + 2)
        @test nfail == 0
        @info "$name: max error $err"
    end

    @testset "pseudodyson: $name" for name in filter(f -> startswith(f, "pseudodyson"), files)
        ref = read_kbref(joinpath(P6_DATA, name))
        push!(consumed, name)
        (; d, k, sig) = p6_meta(ref)
        C = p6_cn(d)
        Σ = PseudoGF(C, sig)
        ref.metadata["sigma"] == "formula" && p6_build!(Σ, 5, 0.2)
        I = Integrator(k)
        G = PseudoGF(C, sig)
        hpath = ref.metadata["hpath"]
        if hpath == "function"
            pseudo_dyson!(G, P6_LAM0, p6_hcf(d), Σ, I, P6_BETA, P6_H)
        elseif hpath == "matrix"
            pseudo_dyson!(G, P6_LAM0, p6_ham(d, 0.0),
                         [p6_ham(d, n * P6_H) for n = 0:P6_NT], Σ, I, P6_BETA, P6_H)
        else
            pseudo_dyson!(G, P6_LAM0, p6_ham(1, 0.0)[1],
                         [p6_ham(1, n * P6_H)[1] for n = 0:P6_NT], Σ, I, P6_BETA, P6_H)
        end
        err = p6_storage(G, ref)
        # herm_pseudo::density_matrix, NESSi tstp = -1 is the Matsubara axis
        drows = filter(r -> r.component == "density", ref.rows)
        @test length(drows) == d * d * (P6_NT + 2)
        nfail = 0
        for r in drows
            ρ = density_matrix(G, r.i + 1)
            v = ρ[r.a+1, r.b+1]
            err = max(err, abs(v - r.value))
            isapprox(v, r.value; atol = 1e-10, rtol = 1e-10) || (nfail += 1)
            # The time slice and the wrapper give the same result
            @test density_matrix(G[r.i+1], r.i + 1) == ρ
            @test density(G, r.i + 1) == ρ
        end
        @test nfail == 0
        err = max(err, p6_start_source(G, Σ, Σ, I, 1.0, ref;
                                       nonzero = ref.metadata["sigma"] == "formula"))
        @info "$name: max error $err"
    end

    @testset "pseudo_vie2: $name" for name in filter(f -> startswith(f, "pseudo_vie2"), files)
        ref = read_kbref(joinpath(P6_DATA, name))
        push!(consumed, name)
        (; d, k, sig) = p6_meta(ref)
        C = p6_cn(d)
        F = PseudoGF(C, sig); Fcc = PseudoGF(C, sig)
        if ref.metadata["kernel"] == "formula"
            p6_build!(F, 6, 0.2)
            p6_build!(Fcc, 7, 0.2)
        end
        Q = p6_build!(PseudoGF(C, sig), 8, 1.0)
        I = Integrator(k)
        G = PseudoGF(C, sig)
        pseudo_vie2!(G, F, Fcc, Q, I, P6_BETA, P6_H)
        err = p6_storage(G, ref)
        if ref.metadata["kernel"] == "formula"
            err = max(err, p6_start_source(G, F, Fcc, I, -1.0, ref))
        end
        @info "$name: max error $err"
    end

    # Every generated file is consumed
    @test consumed == Set(files)
end
